document.addEventListener('change',async event=>{
  const input=event.target;if(!input.matches('[data-photo-upload]'))return;
  const files=[...(input.files||[])];if(!files.length)return;
  const uploader=input.closest('[data-photo-uploader]'),form=input.closest('form'),status=uploader.querySelector('[data-photo-status]'),gallery=uploader.dataset.photoUploader==='gallery';
  const existing=gallery?galleryDraft(form):[];
  const fail=message=>{status.textContent=message;status.classList.add('error');input.value=''};
  if(gallery&&existing.length+files.length>PHOTO_LIMIT){fail(`You can add ${PHOTO_LIMIT-existing.length} more photo${PHOTO_LIMIT-existing.length===1?'':'s'}. Choose fewer files.`);return}
  for(const file of files){const error=photoFileError(file);if(error){fail(error);return}}
  const controls=[...form.querySelectorAll('button')].filter(button=>button.type==='submit'||uploader.contains(button)).map(button=>[button,button.disabled]);
  controls.forEach(([button])=>button.disabled=true);input.disabled=true;form.dataset.uploading='true';uploader.setAttribute('aria-busy','true');status.classList.remove('error');status.textContent=files.length===1?'Preparing your photo…':'Preparing your photos…';
  try{
    const prepared=[];for(const file of files)prepared.push(await preparePhoto(file));
    if(!form.isConnected)return;
    if(gallery)updatePhotoSlots(form,[...existing,...prepared]);
    else{uploader.querySelector('[name="uploadedPhoto"]').value=prepared[0];uploader.querySelector('[data-photo-preview]').innerHTML=`<img src="${prepared[0]}" alt="Selected profile photo preview">`;uploader.querySelector('[data-action="remove-photo"]').hidden=false}
    status.textContent=`${files.length===1?files[0].name:files.length+' photos'} ready. ${gallery?'Save photos':form.dataset.form==='register'?'Register':'Save your profile'} to apply the change.`;
  }catch(error){if(form.isConnected)fail(error.message||'Could not prepare this photo. Try another image.')}
  finally{controls.forEach(([button,disabled])=>button.disabled=disabled);input.disabled=false;input.value='';form.dataset.uploading='false';uploader.removeAttribute('aria-busy');if(gallery&&form.isConnected)form.querySelector('[data-photo-upload-button]').disabled=galleryDraft(form).length>=PHOTO_LIMIT}
});

document.addEventListener('change',e=>{const input=e.target;if(!input.matches('input[name="comfort"]')||!input.checked)return;const group=input.closest('form');if(input.value==='No physical contact')group.querySelectorAll('input[name="comfort"]').forEach(x=>{if(x!==input)x.checked=false});else{const none=group.querySelector('input[name="comfort"][value="No physical contact"]');if(none)none.checked=false}});
document.addEventListener('input',event=>{const input=event.target;if(input.matches('[data-chat-search]')){ui.chatSearch=input.value;applyChatFilters()}if(input.matches('[data-message-input]')){ui.drafts[input.form.dataset.id]=input.value;sizeMessageInput(input)}});
document.addEventListener('keydown',event=>{if(event.target.matches('[data-message-input]')&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();event.target.form.requestSubmit()}});
function updateChatViewport(){document.documentElement?.style.setProperty('--chat-vh',`${window.visualViewport?.height||window.innerHeight}px`)}
window.visualViewport?.addEventListener('resize',updateChatViewport);window.addEventListener?.('resize',updateChatViewport);updateChatViewport();
document.addEventListener('keydown',event=>{if(!ui.modal)return;if(event.key==='Escape'){ui.modal=null;render();return}if(event.key!=='Tab')return;const modal=document.querySelector('[role="dialog"]');if(!modal)return;const controls=[...modal.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary,[tabindex="0"]')].filter(el=>el.getClientRects().length);if(!controls.length)return;const first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
document.addEventListener('change',e=>{const input=e.target,form=input.closest('form');if(!form)return;if(input.matches('select[name="dateType"]')&&['schedule','counter'].includes(form.dataset.form)){const duration=form.querySelector('select[name="duration"]');if(duration)duration.innerHTML=durationOptions(input.value,input.value==='Night out'?4:2)}if(input.matches('select[name="gender"]')){const fields=form.querySelector('[data-female-fields]');if(fields){fields.disabled=input.value!=='female';fields.classList.toggle('hide',fields.disabled)}}if(input.matches('select[name="tattoos"]')){const field=form.querySelector('[data-tattoo-location]');if(field){field.classList.toggle('hide',input.value!=='yes');field.querySelector('input').disabled=input.value!=='yes'}}if(input.matches('input[name="birthday"]')){const hint=form.querySelector('[data-age-preview]');if(hint)hint.textContent=adultBirthday(input.value)?`${age(input.value)} years · calculated from birthday`:'Enter a birthday for a member aged 18 or older.'}});
let swipeInProgress=false;
function commitSwipe(direction,id,kind){swipeInProgress=false;if(direction==='left'){state.swipes.push({from:state.current,to:id,type:'pass'});save();toast(`${nameOf(id)} passed for now`)}else{ui.viewed[kind] ||= [];if(!ui.viewed[kind].includes(id))ui.viewed[kind].push(id);ui.detail=id;render();window.scrollTo(0,0)}}
function animateSwipe(direction,id){if(swipeInProgress)return;const kind=ui.tab,card=document.querySelector('.deck-card');if(!card||!card.getClientRects().length||card.dataset.swipe!==id){if(direction==='right'){ui.detail=id;render();window.scrollTo(0,0)}else{state.swipes.push({from:state.current,to:id,type:'pass'});save();render()}return}swipeInProgress=true;if(!card.animate||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches){commitSwipe(direction,id,kind);return}card.style.setProperty(direction==='left'?'--pass-opacity':'--view-opacity','1');const from=card.style.transform||'translate3d(0,0,0) rotate(0deg)',x=(direction==='left'?-1:1)*Math.max(window.innerWidth,card.offsetWidth*1.5),to=`translate3d(${x}px,-25px,0) rotate(${direction==='left'?-24:24}deg)`;const animation=card.animate([{transform:from,opacity:1},{transform:to,opacity:0}],{duration:330,easing:'cubic-bezier(.2,.75,.2,1)',fill:'forwards'});animation.finished.then(()=>commitSwipe(direction,id,kind)).catch(()=>commitSwipe(direction,id,kind))}
let dragState=null;
function resetDraggedCard(){if(!dragState)return;const card=dragState.card;card.classList.add('snap-back');card.style.transform='translate3d(0,0,0) rotate(0deg)';card.style.setProperty('--pass-opacity','0');card.style.setProperty('--view-opacity','0');setTimeout(()=>card.classList.remove('snap-back'),260);dragState=null}
document.addEventListener('pointerdown',e=>{const card=e.target.closest('.deck-card[data-swipe]');if(!card||e.target.closest('button')||swipeInProgress||e.button!==0)return;dragState={card,id:card.dataset.swipe,pointerId:e.pointerId,x:e.clientX,y:e.clientY,dx:0,active:false};card.setPointerCapture?.(e.pointerId)});
document.addEventListener('pointermove',e=>{const d=dragState;if(!d||d.pointerId!==e.pointerId||swipeInProgress)return;const dx=e.clientX-d.x,dy=e.clientY-d.y;if(!d.active){if(Math.abs(dx)<8||Math.abs(dx)<Math.abs(dy)*1.2)return;d.active=true;d.card.classList.add('dragging')}d.dx=dx;d.card.style.transform=`translate3d(${dx}px,${Math.min(30,Math.abs(dx)*.07)}px,0) rotate(${dx*.045}deg)`;d.card.style.setProperty('--pass-opacity',String(Math.max(0,Math.min(1,-dx/95))));d.card.style.setProperty('--view-opacity',String(Math.max(0,Math.min(1,dx/95))))});
document.addEventListener('pointerup',e=>{const d=dragState;if(!d||d.pointerId!==e.pointerId)return;if(d.active&&Math.abs(d.dx)>Math.min(95,d.card.offsetWidth*.24)){const direction=d.dx<0?'left':'right',id=d.id;dragState=null;animateSwipe(direction,id)}else resetDraggedCard()});
document.addEventListener('pointercancel',resetDraggedCard);
render();
